import{_ as t,o as a,c as i,ak as r}from"./chunks/framework.Cq0X4QeM.js";const d=JSON.parse('{"title":"Privilege escalation","description":"","frontmatter":{"authors":"BlWasp, ShutdownRepo, q-roland, felixbillieres","category":"ad"},"headers":[],"relativePath":"ad/movement/sccm-mecm/privilege-escalation/index.md","filePath":"ad/movement/sccm-mecm/privilege-escalation/index.md"}'),o={name:"ad/movement/sccm-mecm/privilege-escalation/index.md"};function c(n,e,s,l,h,u){return a(),i("div",null,e[0]||(e[0]=[r('<h1 id="privilege-escalation" tabindex="-1">Privilege escalation <a class="header-anchor" href="#privilege-escalation" aria-label="Permalink to &quot;Privilege escalation&quot;">​</a></h1><h2 id="theory" tabindex="-1">Theory <a class="header-anchor" href="#theory" aria-label="Permalink to &quot;Theory&quot;">​</a></h2><p>There are currently three different pathways for privilege escalation in an SCCM environment in order to take control over the infrastructure:</p><ul><li><a href="./credential-harvesting">Credential harvesting</a></li><li><a href="./client-push-coercion">Client Push account authentication coercion</a></li><li><a href="./site-takeover">SCCM site takeover</a></li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><h3 id="credential-harvesting" tabindex="-1">Credential harvesting <a class="header-anchor" href="#credential-harvesting" aria-label="Permalink to &quot;Credential harvesting&quot;">​</a></h3><p>An SCCM infrastructure may contain a wide range of cleartext credentials accessible from various levels of privileges. Some credentials can be associated with privileged accounts in the domain. From a privilege escalation perspective, we are interested in secrets retrievable using an SCCM client or a low-privilege account in the domain.</p><div class="tip custom-block"><p>Read the <a href="./credential-harvesting">credential harvesting</a> article for detailed information on harvesting secrets from SCCM policies and Distribution Points.</p></div><h3 id="client-push-account-authentication-coercion" tabindex="-1">Client Push account authentication coercion <a class="header-anchor" href="#client-push-account-authentication-coercion" aria-label="Permalink to &quot;Client Push account authentication coercion&quot;">​</a></h3><p>If SCCM is deployed via Client Push Accounts, it is possible, from a compromised SCCM client, to coerce the Client Push Account into authenticating to an arbitrary remote resource. It is then possible to retrieve NTLM authentication data in order to crack the account&#39;s password or relay the data to other services. Client Push Accounts are privileged as they are required to have local administrator rights on workstations on which they deploy the SCCM client.</p><div class="tip custom-block"><p>Read the <a href="./client-push-coercion">client push coercion</a> article for detailed information on coercing Client Push account authentication.</p></div><h3 id="sccm-site-takeover" tabindex="-1">SCCM site takeover <a class="header-anchor" href="#sccm-site-takeover" aria-label="Permalink to &quot;SCCM site takeover&quot;">​</a></h3><p>Some SCCM configurations make it possible to abuse the permissions of the site server / passive site server machine accounts in order to compromise the SCCM infrastructure via relay attacks.</p><div class="tip custom-block"><p>Read the <a href="./site-takeover">site takeover</a> article for detailed information on SCCM site takeover techniques.</p></div><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p><a href="https://www.securesystems.de/blog/active-directory-spotlight-attacking-the-microsoft-configuration-manager/" target="_blank" rel="noreferrer">https://www.securesystems.de/blog/active-directory-spotlight-attacking-the-microsoft-configuration-manager/</a></p><p><a href="https://www.synacktiv.com/publications/sccmsecretspy-exploiting-sccm-policies-distribution-for-credentials-harvesting-initial" target="_blank" rel="noreferrer">https://www.synacktiv.com/publications/sccmsecretspy-exploiting-sccm-policies-distribution-for-credentials-harvesting-initial</a></p><p><a href="https://www.hub.trimarcsecurity.com/post/push-comes-to-shove-exploring-the-attack-surface-of-sccm-client-push-accounts" target="_blank" rel="noreferrer">https://www.hub.trimarcsecurity.com/post/push-comes-to-shove-exploring-the-attack-surface-of-sccm-client-push-accounts</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/CRED" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/CRED</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/ELEVATE" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/ELEVATE</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/TAKEOVER" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/TAKEOVER</a></p>',21)]))}const m=t(o,[["render",c]]);export{d as __pageData,m as default};
